import {mountResearch,mountResearchQuality,disposeResearch} from './research-ui.js';
import {DISTRICTS,filterStations,searchStations,mapStations,scenarioMetrics,attachChargerInventory,inventoryDashboard,liveConnection,coreDashboard,seoulOperationsDashboard} from './dashboard-model.js';
import {createStationMap} from './station-map.js';
const icons={bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/>',chart:'<path d="M4 3v17h17M8 16v-4m5 4V8m5 8V5"/>',tool:'<path d="m14 6 4 4m-9 4-6 6 3 2 6-6M14 3a6 6 0 0 0-6 8l5 5a6 6 0 0 0 8-6l-4 3-4-4 3-5z"/>',layers:'<path d="m12 3 10 6-10 6L2 9zM2 13l10 6 10-6M2 17l10 6 10-6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 7M4 12l2 7a8 8 0 0 0 13-3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',pin:'<path d="M19 10c0 6-7 12-7 12S5 16 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>'};
const icon=(n,s=18)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.bolt}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>v==null?'데이터 없음':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:d});
const labels={AVAILABLE:'이용가능',CHARGING:'충전중',STOPPED:'운영중지',UNKNOWN:'상태불확실',COMM_ERROR:'통신이상',MAINTENANCE:'점검',RESTORED:'가상 복구',DELETED:'삭제'};
const time=v=>v?new Date(v).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false}):'관측 대기';
const sum=(rows,k)=>rows.reduce((a,s)=>a+(s.totals?.[k]||0),0);
function operationalSummary(root,rows,t,verified){
 const count=status=>verified?rows.reduce((n,s)=>n+s.chargers.filter(c=>c.display_status===status).length,0):null;
 root.querySelector('#summary').innerHTML=`<article class="stat-card primary"><div class="stat-label">서울 지역 충전시설</div><div class="stat-value" data-kpi="facility_count">${fmt(rows.length)}<span>개소</span></div><div class="stat-bottom">전체 충전기 <b data-kpi="charger_count">${fmt(t.charger_count)}기</b></div></article><div class="status-counts">${[['AVAILABLE','사용가능'],['CHARGING','충전중'],['STOPPED','운영중지'],['MAINTENANCE','점검중'],['COMM_ERROR','통신이상'],['UNKNOWN','상태미확인']].map(([status,label])=>`<div><small>${label}</small><strong data-kpi="${status}">${fmt(count(status))}<em>기</em></strong></div>`).join('')}</div>${[['normal_kw','정상 가용 정격출력','teal'],['stopped_kw','운영중지 정격출력','orange'],['total_kw','확인된 전체 정격출력','']].map(([key,label,color])=>`<article class="stat-card"><div class="stat-label">${label}</div><div class="stat-value ${color}-text" data-kpi="${key}">${fmt(t[key])}<span>kW</span></div><div class="stat-bottom">${key==='normal_kw'?'사용가능 + 충전중':key==='stopped_kw'?'운영중지 · 물리 고장 확정이 아님':'출력 미제공 '+fmt(t.missing_power_count)+'기'}</div></article>`).join('')}<div class="method-note"><p>환경공단 서울 등록 시설의 관측값입니다.<br>현재 필터의 충전소 전체 설비를 집계합니다.</p></div>`;
 root.querySelector('#summary').classList.toggle('classification-pending',!verified);
}
function operationalCharts(root,rows,t){
 const counts=Object.fromEntries(['AVAILABLE','CHARGING','STOPPED','MAINTENANCE','COMM_ERROR','UNKNOWN'].map(status=>[status,rows.reduce((n,s)=>n+s.chargers.filter(c=>c.display_status===status).length,0)]));
 root.querySelector('#charts').innerHTML=`<article class="panel chart-panel"><div class="panel-heading"><h2>관측 운영상태</h2><span class="subtle">충전기 기준</span></div><div class="chart-legend">${[['AVAILABLE','사용가능','teal'],['CHARGING','충전중','teal'],['STOPPED','운영중지','orange'],['MAINTENANCE','점검중','yellow'],['COMM_ERROR','통신이상','gray'],['UNKNOWN','상태미확인','gray']].map(([key,label,color])=>`<div><span><i class="dot ${color}"></i>${label}</span><b>${fmt(counts[key])} <small>기</small></b></div>`).join('')}</div><p class="chart-note">점검·통신이상·상태미확인은 실제 고장으로 확정하지 않습니다.</p></article><article class="panel chart-panel"><div class="panel-heading"><h2>정격출력 구성</h2></div><div class="chart-legend">${[['정상 가용',t.normal_kw],['운영중지',t.stopped_kw],['점검·불확실',t.uncertain_kw]].map(([label,power])=>`<div><span>${label}</span><b>${fmt(power)} <small>kW</small></b></div>`).join('')}</div><p class="chart-note">명목 정격출력 합계이며 실제 동시 공급전력을 뜻하지 않습니다.</p></article>`;
}
async function api(path,options={}){const res=await fetch('/api/v1/'+path,options);const data=await res.json();if(!res.ok)throw new Error(data.detail||'요청 실패');return data;}
/** @param {HTMLElement} root @param {{echarts?:any,maplibregl?:any,L?:any,tileUrl?:string}} lib */
export function mountDashboard(root,lib={}){
 const state={tab:'overview',mode:'live',radius:500,district:'',search:'',searchStation:null,searchOpen:false,searchIndex:-1,searchCandidates:[],charger:null,status:'',qualityFilter:'',powerMin:'',powerMax:'',base:null,sim:null,selected:new Set(),after:false,station:null,quality:null,admin:null,system:null,inventory:null,core:null,coreMatches:null,operations:null,coreBase:null,tablePage:0,alternatives:[],alternativeMessage:'',apiConnected:false,rawDataAvailable:false,d1Available:false,stationMatchingReady:false,analysisDatasetReady:false,classificationVerified:false,statusClassificationVerified:false,chargerTypeClassificationVerified:false,analysisError:'',error:'',loading:false,request:0,scenarioRequest:0,latestId:null,weekday:0,duration:60,maintenance:null,allowedStart:0,allowedEnd:1560};
 let disposed=false,stationMap=null,charts=[],observer=null,toastTimer;
 const tabs=[['overview','map','운영현황'],['priorities','chart','복구 우선순위'],['maintenance','tool','정비시간 분석'],['simulation','layers','복구 시뮬레이션'],['quality','shield','데이터 품질']];
 root.innerHTML=`<div class="app-shell"><aside class="rail"><a href="#" class="rail-logo" aria-label="서울 충전 운영">${icon('bolt',24)}</a><div class="rail-links">${tabs.map(([id,ic,t])=>`<button data-tab="${id}" aria-label="${t}" title="${t}">${icon(ic,21)}</button>`).join('')}</div><span class="rail-bottom">SEOUL<br>2025</span></aside><main><header class="topbar"><div class="brand"><span>SEOUL <b>CHARGE OPS</b></span><small>서울 충전 인프라 운영 대시보드</small></div><div class="top-actions"><span class="source-state"><i></i> 로컬 분석</span><select id="mode" aria-label="데이터 모드"><option value="live">실제 데이터</option><option value="sample">샘플 데이터</option></select><button class="icon-button" data-action="refresh" aria-label="관측 새로고침">${icon('refresh')}</button></div></header><section class="page-heading"><div><p class="eyebrow">INFRASTRUCTURE INTELLIGENCE</p><h1 id="page-title">충전 인프라 운영현황</h1><p class="subtitle">운영상태를 확인하고, 더 효과적인 복구를 계획하세요.</p></div><div class="observation">${icon('clock')}<div><small>운영상태 관측시각 · KST</small><strong id="observed">관측 대기</strong></div></div></section><nav class="tabs" aria-label="화면 선택">${tabs.map(([id,ic,t])=>`<button data-tab="${id}">${t}</button>`).join('')}<span>이용실적 기준 <b>2025년</b></span></nav><div id="notice" aria-live="polite"></div><section class="filterbar" aria-label="시설 필터"><label><span>자치구</span><select id="district" aria-label="자치구"><option value="">서울시 전체</option>${DISTRICTS.map(d=>`<option value="${d}">${d}</option>`).join('')}</select></label><label class="search-label"><span>시설명 검색</span><div>${icon('search',16)}<input id="search" role="combobox" aria-label="시설명 검색" aria-autocomplete="list" aria-expanded="false" aria-controls="station-options" placeholder="충전소 이름을 입력하세요" autocomplete="off"><div id="station-options" role="listbox" aria-label="충전소 검색 결과" hidden></div></div></label><label><span>운영상태</span><select id="status"><option value="">전체 상태</option><option value="NORMAL">정상 운영</option><option value="STOPPED">운영중지</option><option value="MAINTENANCE">점검중</option><option value="UNKNOWN">상태불확실 / 통신이상</option></select></label><label><span>품질</span><select id="qualityFilter"><option value="">전체</option><option value="eligible">분석 적격</option><option value="held">분석 보류</option></select></label><label class="power-filter"><span>총 출력 · kW</span><div><input id="powerMin" type="number" min="0" placeholder="최소"><span>–</span><input id="powerMax" type="number" min="0" placeholder="최대"></div></label><div class="radius-control"><span>대체망 반경</span><div class="segmented"><button data-radius="500" class="active">500m</button><button data-radius="1000">1km</button></div></div><button class="text-button" data-action="filters-reset">필터 초기화</button></section><section class="comparisonbar" hidden><div>${icon('layers',19)}<strong>가상 복구 비교</strong><span id="selection-count">선택한 설비 0기</span><span id="recovered">회복 출력 +0 kW</span></div><div><div class="segmented compare"><button data-view="before" class="active">개선 전</button><button data-view="after">개선 후</button></div><button class="text-button" data-action="reset">${icon('refresh',14)} 전체 초기화</button></div></section><div class="workspace"><aside id="summary" class="summary-column"></aside><section class="map-panel panel"><div class="panel-heading"><div><span class="live-dot"></span><h2>서울시 충전시설 지도</h2><span id="map-count" class="subtle"></span></div><button class="icon-button" data-action="map-reset" aria-label="서울 전체 보기">${icon('pin',16)}</button></div><div id="map" class="map-canvas" aria-label="서울시 충전시설 지도"><div id="offline-map"></div><div class="map-badge">${icon('layers',14)} <span id="map-mode">기준 관측</span></div><div class="map-controls"><button data-action="zoom-in" aria-label="지도 확대">+</button><button data-action="zoom-out" aria-label="지도 축소">−</button></div><div id="tile-notice" class="tile-notice" hidden>배경지도 연결 대기 · 시설 좌표는 표시됩니다.</div></div><div class="map-legend"><span><i class="dot teal"></i>정상 운영</span><span><i class="dot orange"></i>운영중지 포함</span><span><i class="dot yellow"></i>점검중</span><span><i class="dot gray"></i>불확실 / 통신이상</span><span class="network-legend">◌ 주변 대체망</span><small>직선거리 기준</small></div></section><aside id="charts" class="chart-column"></aside></div><section id="content"></section><footer><span><b>SEOUL CHARGE OPS</b> &nbsp; 서울시 급속충전 인프라 운영 분석</span><span>Impact = (D + Q + B) / 3 · <span id="footer-radius">500m</span></span></footer></main><div id="detail-root"></div><div id="toast" role="status" aria-live="polite"></div></div>`;
 const $=s=>root.querySelector(s);
 $('#notice').insertAdjacentHTML('afterend','<div id="operational-observation" class="research-observation" role="status" hidden></div>');
 root.addEventListener('research-open-simulation',()=>{state.tab='simulation';state.station=null;render();});
 root.addEventListener('research-observation',async e=>{const stamp=e.detail.observationAt;root.dataset.recoveryObservationAt=stamp;if(stamp&&state.inventory?.last_success_at!==stamp){try{const r=await fetch('/api/operations/observations?observationAt='+encodeURIComponent(stamp),{cache:'no-store'});if(r.ok&&root.dataset.recoveryObservationAt===stamp){state.inventory=await r.json();state.operations=seoulOperationsDashboard({...state.inventory,include_all:true});renderNotice();}}catch{}}});
 root.addEventListener('research-match-updated',async()=>{try{const r=await fetch('/api/analysis/stations',{cache:'no-store'});if(r.ok){state.core=await r.json();state.coreBase=coreDashboard(state.core);state.base=state.coreBase;renderNotice();}}catch{}});
 function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
 function query(extra={}){return new URLSearchParams({mode:state.mode,radius_m:String(state.radius),...extra}).toString();}
 function current(){if(state.mode==='live'&&state.tab==='overview')return state.operations;return state.tab==='simulation'&&state.after&&state.sim?state.sim.after:state.base;}
 function filtered(data=current()){if(state.mode==='live'&&state.tab==='overview')return filterStations(data?.stations||[],{...state,qualityFilter:''});if(state.tab==='simulation'&&state.sim&&data===state.sim.after){const ids=new Set(filterStations(state.base?.stations||[],state).map(s=>s.id));return data.stations.filter(s=>ids.has(s.id));}return filterStations(data?.stations||[],state);}
 function scopeTotals(rows){const keys=['total_kw','normal_kw','stopped_kw','uncertain_kw','charger_count','normal_count','stopped_count','maintenance_count','uncertain_count','missing_power_count'];return Object.fromEntries(keys.map(k=>[k,rows.some(s=>s.totals?.[k]==null)?null:sum(rows,k)]));}
 function scopeScenario(){const beforeRows=filtered(state.base),afterRows=filtered(state.sim?.after||state.base);const before=scopeTotals(beforeRows),after=scopeTotals(afterRows);return {before,after,...scenarioMetrics(before,after,state.selected,beforeRows,state.base?.priorities||[])};}
 async function load(preserve=false){
  const request=++state.request;state.loading=true;state.error='';if(state.mode==='live'&&state.tab==='overview'&&!state.operations)render();else renderNotice();
  try{
   let base,quality;
   if(state.mode==='live'){
    const read=async path=>{const response=await fetch(path,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error_type||'HTTP '+response.status);return body;};
    // Core data is optional and cannot delay or clear the operational view.
    void read('/api/analysis/stations').then(core=>{
     if(request!==state.request||disposed)return;
     state.core=core;state.coreBase=coreDashboard(core);state.base=state.coreBase;state.analysisError='';
     state.d1Available=core.d1Available===true;state.stationMatchingReady=core.stationMatchingReady===true;
     state.analysisDatasetReady=core.analysisDatasetReady===true;renderNotice();
    }).catch(()=>{if(request===state.request){state.analysisError='핵심시설 API 조회 실패';renderNotice();}});
    const statusRequest=read('/api/system/status').then(system=>{if(request===state.request&&!disposed){state.system=system;renderNotice();}return system;});
    const inventoryRequest=read('/api/chargers').then(async data=>data.stale?{...(await read('/api/operations/observations')),observation_only:true}:data).catch(async error=>{
     // Read-only persisted observations are labelled; never replace failed calls with mocks.
     const saved=await read('/api/operations/observations');
     if(!saved.items?.length)throw error;
     return {...saved,observation_only:true,live_error:error.message};
    });
    void statusRequest.catch(()=>{});
    const inventory=await inventoryRequest;
    if(request!==state.request||disposed)return;
    state.inventory=inventory;
    const connection=liveConnection(state.system,state.inventory);
    Object.assign(state,{apiConnected:connection.connected,rawDataAvailable:connection.dataConnected,
     classificationVerified:connection.classificationVerified,statusClassificationVerified:connection.statusClassificationVerified,
     chargerTypeClassificationVerified:connection.chargerTypeClassificationVerified});
    state.operations=seoulOperationsDashboard({...state.inventory,include_all:true});
    state.coreBase=coreDashboard(state.core||{});base=state.coreBase;
    quality={providers:Object.fromEntries(Object.entries(state.system?.providers||{}).map(([key,value])=>[key,{status:value.connected&&value.current_error===null?'collected':value.current_error?.kind||'not_collected',count:value.count,authenticated_response:value.connected}])),assets:[],candidate_count:0,approved_count:0,collection_enabled:state.system?.collection_enabled};
   }else{
    state.system=null;state.inventory=null;state.core=null;state.operations=null;state.coreBase=null;
    [base,quality]=await Promise.all([api('overview?'+query()),api('data-quality')]);
   }
   if(disposed||request!==state.request)return;state.latestId=base.snapshot_id;state.quality=quality;
   if(!preserve||!state.selected.size){state.base=base;state.sim=null;state.selected.clear();state.after=false;}
   state.tablePage=0;$('#district').value=state.district;
  }catch(e){if(request!==state.request||disposed)return;state.error=e.message;if(state.mode==='live'){state.base=null;state.operations=null;state.inventory=null;state.sim=null;state.selected.clear();}}
  finally{if(request===state.request&&!disposed){state.loading=false;render();}}
 }
 function renderNotice(){root.dataset.dataMode=state.mode;root.classList.toggle('operations-no-data',state.mode==='live'&&state.tab==='overview'&&!state.operations);$('#notice').hidden=state.mode==='live'&&state.tab!=='quality';const b=[];
  if(state.mode==='sample')b.push('<div class="notice sample">DEMO / MOCK DATA · 샘플 데이터</div>');
  else{
   const connection=liveConnection(state.system,state.inventory),summary=state.core?.matching||{};Object.assign(state,{statusClassificationVerified:connection.statusClassificationVerified,chargerTypeClassificationVerified:connection.chargerTypeClassificationVerified,classificationVerified:connection.classificationVerified});
   root.dataset.chargerCount=String(connection.count);root.dataset.storedChargerCount=String(connection.stored);
   root.dataset.coreCount=String(state.core?.total??0);root.dataset.seoulChargerCount=String(state.operations?.displayedChargerCount??0);root.dataset.seoulStationCount=String(state.operations?.displayedStationCount??0);root.dataset.apiConnected=String(connection.connected);root.dataset.rawDataAvailable=String(connection.dataConnected);for(const key of ['d1Available','stationMatchingReady','analysisDatasetReady','classificationVerified','statusClassificationVerified','chargerTypeClassificationVerified'])root.dataset[key]=String(state[key]);
   b.push(`<div class="notice" id="api-connection">[환경공단 API] ${connection.connected?'연결됨':state.loading?'확인 중':'연결 실패'}</div>`);
   b.push(`<div class="notice" id="data-connection">[환경공단 원자료] ${connection.dataConnected?'연결됨':state.loading?'데이터 불러오는 중':'조회 상태 확인 필요'} · <span id="stored-count">${fmt(connection.stored)}개 충전기 저장</span></div>`);
   b.push(`<div class="notice" id="operations-connection">[\uc11c\uc6b8 \uc6b4\uc601\ud604\ud669] ${state.operations?.stations.length?'\ud45c\uc2dc \uac00\ub2a5':'\ub370\uc774\ud130 \ud655\uc778 \uc911'} \u00b7 \uc11c\uc6b8 \uc9c0\uc5ed \ud45c\uc2dc \ub300\uc0c1 ${fmt(state.operations?.displayedChargerCount)}\uae30 / ${fmt(state.operations?.displayedStationCount)}\uac1c \ucda9\uc804\uc18c</div>`);
   b.push(`<div class="notice" id="core-connection">[핵심 분석대상] ${state.core?.total?state.core.total+'개 시설 연결 완료':!state.core?(state.analysisError?'핵심시설 API 조회 실패':state.loading?'데이터 불러오는 중':'핵심시설 데이터 없음'):!state.d1Available?'D1 실제 충전량 원자료 필요':state.stationMatchingReady?'핵심 분석시설 매칭 준비 중':'핵심 분석시설 매칭 준비 중'}${state.core?' · 확정 '+(summary.confirmed??0)+' / 검토 '+(summary.review??0)+' / 미매칭 '+(summary.unmatched??0):''}</div>`);
   b.push(`<div class="notice" id="classification-status"><span id="status-classification">[운영상태 코드] ${state.statusClassificationVerified?'검증 완료':'공식 v1.25 코드표 확인 필요'}</span> · <span id="type-classification">[급속/완속 코드] ${state.chargerTypeClassificationVerified?'검증 완료':'커넥터 코드 확인 / 급속 분류 근거 확인 필요'}</span></div>`);
   if(state.inventory?.stale)b.push('<div class="notice" id="observation-freshness">[현재 운영상태] 관측 유효기간 초과 · 최신 수집 확인 필요. 지도와 원본 코드는 마지막 성공 관측입니다.</div>');
   if(state.error)b.push(`<div class="notice error">${connection.connected?'원자료 조회 상태 확인 필요':'환경공단 연결 실패'} · ${esc(state.error)}</div>`);
  }
  $('#notice').innerHTML=b.join('');
  const observation=$('#operational-observation');
  observation.hidden=state.mode!=='live'||state.tab!=='overview'||!state.inventory?.observation_only;
  observation.textContent=state.inventory?.observation_only?`저장된 실제 관측 · ${time(state.inventory.last_success_at)} · 최신 조회 대기 중이며 현재 상태와 다를 수 있습니다.`:'';
 }
 function render(){root.classList.toggle('research-active',state.mode==='live'&&['priorities','maintenance','simulation','quality'].includes(state.tab));const focusId=document.activeElement?.dataset?.charger;charts.forEach(c=>c.dispose());charts=[];$('#page-title').textContent=state.mode==='live'&&state.tab==='overview'?'서울 지역 환경공단 충전소 운영현황':tabs.find(t=>t[0]===state.tab)[2];$('.map-panel .panel-heading h2').textContent=state.mode==='live'&&state.tab==='overview'?'서울 지역 환경공단 등록 충전소':'핵심 분석시설 지도';root.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-current',b.dataset.tab===state.tab?'page':'false');});root.querySelectorAll('[data-radius]').forEach(b=>b.classList.toggle('active',Number(b.dataset.radius)===state.radius));root.querySelectorAll('[data-view]').forEach(b=>{const a=(b.dataset.view==='after')===state.after;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a));});$('#observed').textContent=time(current()?.observed_at);$('#footer-radius').textContent=state.radius===1000?'1km':'500m';$('#selection-count').textContent=state.base?`선택한 설비 ${(state.base.priorities||[]).filter(r=>state.selected.has(r.charger_id)&&filtered(state.base).some(s=>s.id===r.station_id)).length}기`:'선택 설비 데이터 없음';$('#recovered').textContent=state.base?`회복 출력 +${fmt(scopeScenario().recovered_kw)} kW`:'회복 출력 데이터 미수집';$('.comparisonbar').hidden=state.tab!=='simulation';$('.workspace').classList.toggle('analysis-only',['maintenance','quality'].includes(state.tab));$('#map-mode').textContent=state.tab==='simulation'&&state.after?'가상 복구 시나리오':'현재 API 관측';const rows=filtered(),t=scopeTotals(rows);renderNotice();renderSummary(rows,t);renderCharts(rows,t);renderMap(rows);renderContent(rows);renderDetail();renderAutocomplete();if(focusId){const nodes=[...root.querySelectorAll('input[data-charger]')];nodes.find(n=>n.dataset.charger===focusId)?.focus();}}
 function renderAutocomplete(){const input=$('#search'),list=$('#station-options');state.searchCandidates=searchStations((current()?.stations||[]).filter(s=>!state.district||s.district===state.district),state.search,state.district).slice(0,200);input.setAttribute('aria-expanded',String(state.searchOpen));list.hidden=!state.searchOpen;if(!state.searchOpen){input.removeAttribute('aria-activedescendant');return;}list.innerHTML=state.searchCandidates.length?state.searchCandidates.map((s,i)=>`<button type="button" role="option" id="station-option-${i}" tabindex="-1" data-search-result="${esc(s.id)}" aria-selected="${i===state.searchIndex}"><span>${esc(s.name)}</span><small>${esc(s.district)}${s.quality_flags.length?' · 상태 확인 필요':''}</small></button>`).join(''):'<div class="autocomplete-empty">'+(state.base?'검색 결과 없음':'데이터 미수집 · 검색할 충전소 데이터 없음')+'</div>';if(state.searchIndex>=0&&state.searchCandidates[state.searchIndex]){input.setAttribute('aria-activedescendant',`station-option-${state.searchIndex}`);list.children[state.searchIndex]?.scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');}
 function chooseSearch(id){const s=current()?.stations.find(s=>s.id===id);if(!s)return;if(state.district&&state.district!==s.district){state.district=DISTRICTS.includes(s.district)?s.district:'';$('#district').value=state.district;}state.search=s.name;state.searchStation=s.id;state.searchOpen=false;state.searchIndex=-1;if(!filterStations([s],state).length){for(const k of ['status','qualityFilter','powerMin','powerMax']){state[k]='';$('#'+k).value='';}toast('선택 시설 표시를 위해 상태·품질·출력 필터를 초기화했습니다.');}$('#search').value=s.name;state.station=s.id;state.charger=null;render();stationMap?.flyTo(s);$('#detail-title')?.focus();}
 function renderRanking(rows){const ids=new Set(rows.map(s=>s.id));const ranks=(current()?.priorities||[]).filter(r=>ids.has(r.station_id));$('#charts').innerHTML=`<article class="panel ranking-panel" aria-label="복구 우선순위 순위표"><div class="panel-heading"><h2>복구 우선순위</h2><span class="subtle">${state.base?`${ranks.length}기`:'데이터 미수집'}</span></div><p class="ranking-method">Impact = (D + Q + B) / 3<br>2025년 최근 실제 이용실적 기반 · 0~1</p><div class="ranking-list">${ranks.length?ranks.map((r,i)=>`<button class="ranking-row ${i<3?'top-ranking':''} ${state.charger===r.charger_id?'active':''}" data-station="${esc(r.station_id)}" data-focus-charger="${esc(r.charger_id)}"><span class="rank ${i<3?'top-rank':''}">${i+1}</span><div><b>${esc(r.name)}</b><small>${esc(r.charger_id)}</small><small>${fmt(r.power_kw)} kW · 운영중지</small></div><strong>${fmt(r.score,3)}</strong></button>`).join(''):'<p class="empty-cell">'+(state.base?'이 조건의 복구 순위 없음':'데이터 미수집 · 데이터 없음')+'</p>'}</div><p class="chart-note">알수없음·통신이상은 물리적 고장으로 분류하지 않습니다.</p></article>`;}
 function analysisInfo(rows,t){if(state.tab==='maintenance')return `<article class="panel analysis-context"><div class="panel-heading"><h2>정비 분석 기준</h2></div><dl><dt>선택 자치구</dt><dd>${esc(state.district||'서울시 전체')}</dd><dt>시설</dt><dd>${state.base?rows.length+'개소':'데이터 미수집'}</dd><dt>최근 실제 이용실적</dt><dd>2025년</dd><dt>후보 길이</dt><dd>60분 / 120분</dd><dt>최소 유효 표본</dt><dd>요일별 20일</dd></dl><p class="chart-note">급속 전용 이력·커버리지 근거가 없으면 추천을 보류합니다.</p></article>`;return `<article class="panel analysis-context"><div class="panel-heading"><h2>관측과 자료 출처</h2></div><dl><dt>API 관측시각</dt><dd>${time(state.mode==='sample'?state.quality?.observed_at:state.base?.observed_at)}</dd><dt>출력미상</dt><dd>${state.base?fmt(t.missing_power_count)+'기':'데이터 없음'}</dd><dt>불확실 / 통신이상</dt><dd>${state.base?fmt(t.uncertain_count)+'기':'데이터 없음'}</dd><dt>운영상태 출처</dt><dd>한국환경공단</dd><dt>이용실적</dt><dd>서울시 XLSX · 2025년</dd></dl></article>`;}

 function renderSummary(rows,t){if(state.mode==='live'&&state.tab==='overview'){operationalSummary(root,rows,t,state.statusClassificationVerified);return;}const connected=Boolean(current()),value=k=>state.mode==='live'&&current()?.stale&&!current()?.observation_only?'최신 관측 필요':state.mode==='live'&&!state.statusClassificationVerified?'분류 검증 중':fmt(connected?t[k]:null),ratio=t.total_kw?Math.round(t.normal_kw/t.total_kw*100):0;$('#summary').classList.toggle('classification-pending',state.mode==='live'&&!state.statusClassificationVerified);$('#summary').innerHTML=`<article class="stat-card primary"><div class="stat-label">${state.mode==='live'&&state.tab==='overview'?'서울 지역 충전시설':'분석대상 충전시설'} ${icon('pin',17)}</div><div class="stat-value" data-kpi="facility_count">${connected?fmt(rows.length):'분석 결과 준비 중'}<span>${connected?'개소':''}</span></div><div class="stat-bottom">${state.mode==='live'&&state.tab==='overview'?(state.chargerTypeClassificationVerified?'서울 지역 급속충전기':'서울 지역 원자료 충전기'):'핵심 분석대상 급속충전기'} <b data-kpi="charger_count">${state.mode==='live'&&state.tab==='overview'?fmt(t.charger_count):value('charger_count')}${connected?'기':''}</b></div></article><div class="status-counts">${[['normal_count','정상 운영','teal'],['stopped_count','운영중지','orange'],['maintenance_count','점검중','yellow'],['uncertain_count','불확실 / 통신이상','gray']].map(([k,l,c])=>`<div><small><i class="dot ${c}"></i>${l}</small><strong data-kpi="${k}">${value(k)}<em>${connected&&(state.mode!=='live'||state.statusClassificationVerified)?'기':''}</em></strong></div>`).join('')}</div>${state.mode==='live'&&state.tab==='overview'?`<div class="status-counts">${[['AVAILABLE','사용가능'],['CHARGING','충전중'],['COMM_ERROR','통신이상'],['UNKNOWN','상태미확인 / 기타']].map(([status,label])=>`<div><small>${label}</small><strong>${current()?.stale&&!current()?.observation_only?'최신 관측 필요':state.statusClassificationVerified?fmt(rows.reduce((count,s)=>count+s.chargers.filter(c=>c.display_status===status).length,0)):'분류 검증 중'}</strong></div>`).join('')}</div>`:''}${[['teal','현재 정상 가용 정격출력','normal_kw','이용가능 + 충전중'],['orange','운영중지 정격출력','stopped_kw','물리 고장 확정량이 아님'],['gray','상태불확실·점검 출력','uncertain_kw','정상·중지에 임의 편입하지 않음']].map(([c,l,k,n])=>`<article class="stat-card"><div class="stat-label"><i class="dot ${c}"></i>${l}</div><div class="stat-value ${c}-text" data-kpi="${k}">${value(k)}<span>${connected&&(state.mode!=='live'||state.statusClassificationVerified)?'kW':''}</span></div>${k==='normal_kw'&&connected?`<div class="progress"><span style="width:${ratio}%"></span></div>`:''}<div class="stat-bottom"><span>${n}</span></div></article>`).join('')}${state.mode==='live'&&state.tab==='overview'?`<article class="stat-card"><div class="stat-label">확인된 원자료 정격출력 합계</div><div class="stat-value" data-kpi="total_kw">${fmt(t.total_kw)}<span>kW</span></div><div class="stat-bottom">출력 미제공 ${fmt(t.missing_power_count)}기 별도</div></article>`:''}<div class="method-note">${icon('shield',18)}<div><b>${esc(state.district||'서울시 전체')} · ${state.radius}m</b><p>2025년 최근 실제 이용실적<br>선택 시설의 전체 설비 기준</p><small>출력미상 ${value('missing_power_count')}${connected?'기':''} · 관측 ${time(current()?.observed_at)}</small></div></div>`;}
 function renderCharts(rows,t){if(state.mode==='live'&&state.tab==='overview'){operationalCharts(root,rows,t);return;}if(state.tab==='priorities'){renderRanking(rows);return;}if(['maintenance','quality'].includes(state.tab)){$('#charts').innerHTML=analysisInfo(rows,t);return;}const max=t.total_kw||1,n=t.normal_kw/max*100,o=t.stopped_kw/max*100;const monthly=Array.from({length:12},(_,i)=>rows.length&&rows.every(s=>s.monthly_kwh?.[i]!=null)?rows.reduce((a,s)=>a+s.monthly_kwh[i],0):null),high=Math.max(1,...monthly.map(v=>v||0));$('#charts').innerHTML=`<article class="panel chart-panel"><div class="panel-heading"><h2>출력 구성</h2><span class="subtle">kW 기준</span></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(#0b9585 0 ${n}%,#ed8a40 ${n}% ${n+o}%,#aab4c2 ${n+o}% 100%)"><div><small>정상 운영 비중</small><strong class="${state.mode==='live'&&!state.statusClassificationVerified?'classification-pending':''}">${state.mode==='live'&&!state.statusClassificationVerified?'분류 확인 중':t.total_kw?fmt(n,1):'—'}<span>${state.mode==='live'&&!state.statusClassificationVerified?'':'%'}</span></strong></div></div></div><div class="chart-legend">${[['teal','정상 운영',t.normal_kw],['orange','운영중지',t.stopped_kw],['gray','상태불확실',t.uncertain_kw]].map(([c,l,v])=>`<div><span><i class="dot ${c}"></i>${l}</span><b>${state.mode==='live'&&!state.statusClassificationVerified?'분류 검증 중':fmt(current()?v:null)} <small>${current()?'kW':''}</small></b></div>`).join('')}</div></article><article class="panel chart-panel demand-chart"><div class="panel-heading"><h2>월별 급속충전량</h2><span class="subtle">2025년</span></div><div class="chart-unit">kWh / 월 · 최근 실제 이용실적</div><div id="demand-chart" class="bar-chart" role="img" aria-label="2025년 월별 충전량: ${monthly.map((v,i)=>`${i+1}월 ${fmt(v)} kWh`).join(', ')}">${monthly.map((v,i)=>`<div class="bar-column"><div title="${i+1}월 ${fmt(v)} kWh" class="bar ${v==null?'missing':''}" style="height:${v==null?2:Math.max(2,v/high*100)}%"></div><small>${i+1}</small></div>`).join('')}</div><p class="chart-note">${monthly.some(v=>v==null)?'결측월은 자료 없음으로 표시합니다.':'현재 필터에 포함된 시설의 월별 합계'}</p></article>`;if(lib.echarts){const host=$('#demand-chart');host.innerHTML='';host.classList.add('echarts-host');const chart=lib.echarts.init(host);chart.setOption({grid:{top:15,right:6,left:40,bottom:24},tooltip:{trigger:'axis',valueFormatter:v=>`${fmt(v)} kWh`},xAxis:{type:'category',data:monthly.map((_,i)=>i+1),axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:10,color:'#8693a3'}},yAxis:{type:'value',axisLabel:{fontSize:9,formatter:v=>`${v/1000}k`},splitLine:{lineStyle:{color:'#edf1f5'}}},series:[{type:'bar',data:monthly,itemStyle:{color:'#0b9585',borderRadius:[3,3,0,0]},barMaxWidth:14}]});charts.push(chart);}}
 function renderMap(rows){if(state.mode==='live'&&state.tab!=='overview')return;const stations=mapStations(current(),rows).filter(s=>state.mode!=='live'||rows.some(r=>r.id===s.id));if(state.mode==='live'&&rows.some(s=>s.id===state.station))stations.push(...state.alternatives);$('#map-count').textContent=current()?(current().provider_inventory?`${stations.length}개소 관측 · ${state.base.inventory_only?'분석 근거 검증 대기':'분석대상 '+rows.length+'개소'}`:`${rows.length}개소 · 주변 ${stations.filter(s=>s.map_role==='alternative').length}개소`):'데이터 미수집';if(!stationMap)stationMap=createStationMap($('#map'),lib,id=>selectStation(id));stationMap.update(stations,state.station,state.radius);}
 function priorityTable(rows){const ids=new Set(rows.map(s=>s.id)),all=[...(current()?.priorities||[]),...(current()?.held||[])].filter(r=>ids.has(r.station_id));return `<div class="table-wrap"><table><thead><tr>${state.tab==='simulation'?'<th>복구 선택</th>':''}<th>순위</th><th>시설명 / 설비 ID</th><th>자치구</th><th>상태</th><th>출력</th><th>주변 대체망</th><th>영향도</th><th>산정 근거</th></tr></thead><tbody>${all.length?all.map(r=>`<tr class="${state.selected.has(r.charger_id)?'selected-row':''}">${state.tab==='simulation'?`<td><input type="checkbox" data-charger="${esc(r.charger_id)}" aria-label="${esc(r.name)} ${esc(r.charger_id)} 복구 선택" ${state.selected.has(r.charger_id)?'checked':''} ${r.eligible?'':'disabled'} title="${esc(r.reasons.join(' · '))}"></td>`:''}<td><span class="rank ${r.rank<=3?'top-rank':''}">${r.rank||'—'}</span></td><td><button class="station-link" data-station="${esc(r.station_id)}" data-focus-charger="${esc(r.charger_id)}">${esc(r.name)}</button><small class="cell-sub">${esc(r.charger_id)}</small></td><td>${esc(r.district)}</td><td><span class="badge ${r.eligible?'stopped':'uncertain'}">${r.eligible?'운영중지':'분석 보류'}</span></td><td><b>${fmt(r.power_kw)}</b> <small>kW</small></td><td>${fmt(r.alternative_kw)} <small>kW</small></td><td><span class="score">${fmt(r.score,3)}</span></td><td class="reason-cell">${r.eligible?`(D ${fmt(r.demand_factor,3)} + Q ${fmt(r.share_factor,3)} + B ${fmt(r.shortage_factor,3)}) / 3`:esc(r.reasons.join(' · '))}</td></tr>`).join(''):`<tr><td colspan="9" class="empty-cell">${state.base?'이 조건에 해당하는 미복구 설비가 없습니다.':'실관측을 연결하거나 샘플 데이터를 선택하세요.'}</td></tr>`}</tbody></table></div>`;}
 function stationsTable(rows){state.tablePage=Math.min(state.tablePage,Math.max(0,Math.ceil(rows.length/100)-1));const shown=rows.slice(state.tablePage*100,(state.tablePage+1)*100);return `<div class="table-wrap"><table><thead><tr><th>시설명</th><th>자치구</th><th>${current()?.operations_dataset&&!state.classificationVerified?'충전기 원자료':'급속 설비'}</th><th>정상 / 중지 / 불확실</th><th>총 정격출력</th><th>${current()?.operations_dataset?'유형 / 상태 원본 코드':'2025년 급속충전량'}</th><th>${current()?.operations_dataset?'관측대상':'품질'}</th><th></th></tr></thead><tbody>${rows.length?shown.map(s=>`<tr><td><button class="station-link" data-station="${esc(s.id)}">${esc(s.name)}</button><small class="cell-sub">${esc(s.address)}</small></td><td>${esc(s.district)}</td><td>${s.totals.charger_count}기</td><td><span class="teal-text">${fmt(s.totals.normal_kw)}</span> / <span class="orange-text">${fmt(s.totals.stopped_kw)}</span> / ${fmt(s.totals.uncertain_kw)} <small>kW</small></td><td><b>${fmt(s.totals.total_kw)}</b> <small>kW</small></td><td>${current()?.operations_dataset?esc([...new Set(s.chargers.map(c=>c.chgerType??'?'))].join(', ')+' / '+[...new Set(s.chargers.map(c=>c.stat??'?'))].join(', ')):fmt(s.annual_kwh)} <small>${current()?.operations_dataset?'':'kWh'}</small></td><td><span class="badge ${s.quality_flags.length?'uncertain':'normal'}">${current()?.operations_dataset?'환경공단 등록 시설':(s.quality_flags.length?'분석 보류':'적격')}</span></td><td><button class="icon-button" data-station="${esc(s.id)}" aria-label="${esc(s.name)} 상세">${icon('arrow',16)}</button></td></tr>`).join(''):'<tr><td colspan="8" class="empty-cell">표시할 시설이 없습니다. 데이터 모드와 필터를 확인하세요.</td></tr>'}</tbody></table></div>`;}
 const exportButton=()=>`<button class="secondary-button" data-action="export">${icon('download',15)} CSV 내보내기</button>`;
 function renderContent(rows){if(state.mode==='live'&&state.tab==='overview'&&state.loading&&!state.operations){$('#content').innerHTML='<article class="panel empty-cell" role="status">데이터 불러오는 중</article>';return;}if(state.mode==='live'&&['priorities','maintenance','simulation'].includes(state.tab)){mountResearch($('#content'),state.tab,lib,()=>{state.tab='quality';render();},{observationAt:state.inventory?.last_success_at});return;}if(state.mode==='live'&&state.tab==='quality'){mountResearchQuality($('#content'),lib);return;}disposeResearch();let html='';if(state.tab==='overview')html=`${state.error?'<article class="panel"><h2>현재 충전소 데이터를 불러오지 못했습니다.</h2><p>자료 상태를 확인하고 최신 수집 후 새로고침해주세요.</p><button data-tab="quality">데이터 품질 확인</button></article>':''}<article class="panel list-panel"><div class="section-heading"><div><h2>충전시설 목록 <span class="count-pill">${rows.length}</span></h2><p>지도와 같은 관측·필터 기준입니다. 시설을 선택해 상세 정보를 확인하세요.</p></div>${exportButton()}</div>${stationsTable(rows)}${rows.length>100?`<div class="section-heading"><button data-action="stations-prev" ${state.tablePage===0?'disabled':''}>\uc774\uc804</button><span>${state.tablePage+1} / ${Math.ceil(rows.length/100)} \ud398\uc774\uc9c0 \u00b7 \uc804\uccb4 ${rows.length}\uac1c\uc18c</span><button data-action="stations-next" ${state.tablePage>=Math.ceil(rows.length/100)-1?'disabled':''}>\ub2e4\uc74c</button></div>`:''}</article>`;if(state.tab==='priorities')html=`<article class="panel list-panel"><div class="section-heading"><div><h2>복구 우선순위</h2><p>운영중지 설비의 상대 영향도(0~1) · (D + Q + B) / 3. 행을 눌러 근거를 확인하세요.</p></div>${exportButton()}</div>${priorityTable(rows)}</article>`;
 if(state.tab==='simulation')html=simulationView(rows);
 if(state.tab==='maintenance')html=maintenanceView(rows);if(state.tab==='quality')html=qualityView();$('#content').innerHTML=html;}
 function maintenanceView(rows){const s=(current()?.stations||[]).find(s=>s.id===state.station)||rows[0];if(s&&!state.station)state.station=s.id;const m=state.maintenance,h=state.maintenance?.hourly,max=Math.max(1,...(h?.values||[]).flat());return `<article class="panel"><div class="section-heading"><div><h2>계획정비 후보시간</h2><p>유효 세션과 후보창의 중첩분을 비교합니다. 분석기간 2025년.</p></div></div><div class="maintenance-controls"><select id="maintenanceStation" aria-label="정비 분석 시설">${rows.map(r=>`<option value="${esc(r.id)}" ${s?.id===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><select id="weekday" aria-label="요일">${['월','화','수','목','금','토','일'].map((d,i)=>`<option value="${i}" ${state.weekday===i?'selected':''}>${d}요일</option>`).join('')}</select><select id="duration" aria-label="정비 길이"><option value="60" ${state.duration===60?'selected':''}>60분</option><option value="120" ${state.duration===120?'selected':''}>120분</option></select><label>작업시작 <input id="allowedStart" type="number" min="0" max="1439" value="${state.allowedStart}" aria-label="작업 가능 시작 분"></label><label>작업종료 <input id="allowedEnd" type="number" min="1" max="1560" value="${state.allowedEnd}" aria-label="작업 가능 종료 분"></label><button class="secondary-button" data-action="maintenance">후보 계산</button></div><div class="maintenance-results">${m?m.candidates.length?m.candidates.map((c,i)=>`<div class="candidate"><small>추천 ${i+1}</small><strong>${Math.floor(c.start_minute/60)}:${String(c.start_minute%60).padStart(2,'0')} · ${c.duration_minutes}분</strong><p>평균 ${fmt(c.mean_session_minutes,1)} 세션·분 / ${c.valid_days}일</p></div>`).join(''):`<div class="hold-message">${icon('shield',25)}<div><h3>자동 정비 추천 보류</h3><p>${esc(m.reasons.join(' · '))}</p><small>유효 관측일 ${m.valid_days}일 · 누락일을 미이용 0으로 채우지 않습니다.</small></div></div>`:'<div class="hold-message"><div><h3>시설을 선택하고 후보 계산을 실행하세요.</h3><p>분석기간 급속 전용 이력, 커버리지 근거, 요일별 20일 이상 표본을 확인합니다.</p></div></div>'}</div></article><article class="panel heatmap-panel"><div class="section-heading"><div><h2>요일·시간별 세션 중첩</h2><p>선택 시설의 2025년 실제 세션 · 급속/완속 미구분 · 정비 추천에 자동 사용하지 않습니다.</p></div><span class="subtle">적음 ░ ▒ ▓ 많음</span></div>${h?`<div class="heatmap"><div></div>${Array.from({length:24},(_,i)=>`<span>${i}</span>`).join('')}${h.values.map((r,i)=>`<span>${['월','화','수','목','금','토','일'][i]}</span>${r.map((v,j)=>`<div tabindex="0" style="background:rgba(11,149,133,${.08+v/max*.9})" title="${i+1}요일 ${j}시 ${fmt(v)} 세션·분" aria-label="${i+1}요일 ${j}시 ${fmt(v)} 세션·분"></div>`).join('')}`).join('')}</div>`:'<p class="empty-cell">시설을 선택하고 후보 계산을 실행하세요. 연결된 세션이 없으면 데이터 없음으로 표시합니다.</p>'}</article>`;}
 function qualityView(){const q=state.quality;if(!q)return '<article class="panel empty-cell">품질 보고서를 불러오지 못했습니다.</article>';const names={connection_pending:'키 설정 대기',collection_pending:'수집 실행 대기',collected:'수집 완료',schema_review_required:'필드 매핑 검토 필요',endpoint_unconfigured:'호출 주소 설정 대기',authentication:'인증 오류',quota:'호출 한도 초과',network_error:'네트워크 오류',invalid_schema:'응답 구조 확인 필요'};let out=`<article class="panel"><div class="section-heading"><div><h2>수집과 데이터 품질</h2><p>실제 원자료 검사 결과 · 승인 전 시설은 공식 순위에서 제외합니다.</p></div><button class="secondary-button" data-action="admin">시설 매칭 검토</button></div><div class="quality-grid">${Object.entries(q.providers).filter(([p])=>p!=='KEPCO').map(([p,s])=>`<div class="quality-card"><small>${p==='ME'?'한국환경공단 · 기본 출처':'한국전력공사 · 교차검증'}</small><h3>${esc(names[s.status]||s.status)}</h3><p>${s.count!=null?`${fmt(s.count)}건${s.pages!=null?" / "+s.pages+"페이지":""}`:'서버 .env에서 연결 설정'}</p><small>${s.authenticated_response?'인증 응답 수신 · 코드/설비 검증은 별도':'인증 실응답 미검증'}</small></div>`).join('')}<div class="quality-card"><small>원자료 급속 시설 후보</small><h3>${q.candidate_count} <span>개 명칭</span></h3><p>실제 승인 ${q.approved_count}개 · 명칭과 시설은 구분합니다.</p></div></div><div class="source-reports">${(q.assets||[]).map(a=>`<div class="source-report"><h3>${esc(a.file)}</h3><p>고유 시설명 ${a.unique_station_names}개 ${a.fast_station_names!=null?`· 급속 ${a.fast_station_names}개`:''}</p>${a.sheets.map(s=>`<div class="quality-numbers"><span><b>${fmt(s.rows)}</b>원본 행</span><span><b>${fmt(s.missing_rows)}</b>결측 행</span><span><b>${fmt(s.negative_rows)}</b>음수 행</span><span><b>${fmt(s.duplicate_excess_rows)}</b>동일 행 초과</span><span><b>${fmt(s.duplicate_group_rows)}</b>동일 그룹 전체</span></div><p>플래그: ${esc(JSON.stringify(s.quality_flags))}</p>`).join('')}<code>SHA-256 ${esc(a.sha256)}</code>${a.unit_warning?`<p class="orange-text">${esc(a.unit_warning)}</p>`:''}</div>`).join('')}</div></article>`;
 if(state.mode==='live')out+='<article class="panel"><p class="chart-note">한전 교차검증: 현재 미사용</p></article>';if(state.mode==='live'&&state.core){const d=state.core.d1||{};out+=`<article class="panel"><div class="section-heading"><h2>D1-D3 핵심 분석대상</h2><a href="/live">환경공단 원자료 보기</a></div><p class="chart-note">D1: ${esc(d.path||'원자료 필요')}<br>실제 컬럼: ${esc((d.columns||[]).join(' / '))}<br>전체 고유명 ${d.unique_station_names??'미확인'} / 급속 기록 고유명 ${d.fast_station_names??'미확인'}<br>이름 점수는 후보 생성용이며 자동 confirmed로 처리하지 않습니다.</p></article>`;if(state.coreMatches)out+=`<article class="panel"><h2>시설 매칭 검토</h2><div class="table-wrap"><table><thead><tr><th>D1 원본명</th><th>D3 후보</th><th>주소</th><th>상태</th><th>검토 메모</th></tr></thead><tbody>${state.coreMatches.items.map(m=>`<tr><td>${esc(m.d1_station_name)}</td><td>${esc(m.d3_station_name||'후보 없음')}<small>${esc(m.candidate_stat_id)}</small></td><td>${esc(m.d3_address||'')}</td><td>${esc(m.match_status)}</td><td>${esc(m.review_note||'')}</td></tr>`).join('')}</tbody></table></div></article>`;}
 if(state.admin){const a=state.admin;out+=`<article class="panel admin-panel"><div class="section-heading"><div><h2>로컬 관리자 · 매칭 검토</h2><p>명칭 유사도는 후보 생성용입니다. 주소·좌표·급속 설비를 확인하고 근거를 기록하세요.</p></div></div><form id="match-form"><label>원자료 시설명<select name="source_name" id="matchSource" required><option value="">선택하세요</option><option value="__external_network__">외부 대체망 설비 검토 · 실적 연결 없음</option>${a.source_names.map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><label>수집 시설<select name="station_id" required><option value="">선택하세요</option>${a.stations.map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${esc(s.address)}</option>`).join('')}</select></label><div id="match-candidates" class="match-candidates">${a.stations.length?'원자료 명칭을 선택하면 후보를 표시합니다.':'실관측 수집 후 매칭 후보를 생성할 수 있습니다.'}</div><label>검토상태<select name="status"><option value="review_required">검토 필요</option><option value="approved">승인</option><option value="rejected">반려</option><option value="unmatched">미매칭</option></select></label><label>검토자<input name="reviewer" required></label><label class="wide-field">주소·좌표·설비 확인 근거<textarea name="evidence" rows="3" required placeholder="확인 자료와 동일 시설 판단 근거"></textarea></label><div class="wide-field verify-flags">${[['physical_verified','커넥터 중복 없는 독립 물리 설비 확인'],['sharing_verified','출력 공유 없는 독립 설비 확인'],['access_verified','접근·운영시간 확인'],['compatible_verified','호환성 확인'],['fast_only_history_verified','2025년 급속 전용 이력 확인']].map(([n,l])=>`<label><input name="${n}" type="checkbox">${l}</label>`).join('')}<p>공유 설비는 현재 정밀 복구 선택에서 제외합니다. 커버리지 근거는 서버에 별도 등록해야 합니다.</p></div><label>관리자 토큰<input name="token" type="password" required autocomplete="off"></label><div class="form-action"><button class="primary-button" type="submit">검토 저장</button><small>토큰은 메모리에서만 사용합니다.</small></div></form><div class="match-history">${a.matches.map(m=>`<p><b>${esc(m.source_name)}</b> → ${esc(m.station_id)} · ${esc(m.status)} · ${esc(m.reviewer)}<br><small>${esc(m.evidence)}</small></p>`).join('')}</div></article>`;}return out;}
 function simulationView(rows){const m=scopeScenario(),b=m.before,a=m.after,connected=state.mode==='sample'?Boolean(state.base):state.analysisDatasetReady&&state.classificationVerified&&Boolean(state.base?.analysis_run_id),show=v=>fmt(connected?v:null),list=(state.base?.priorities||[]).filter(r=>state.selected.has(r.charger_id)&&filtered(state.base).some(s=>s.id===r.station_id));return `<article class="panel simulation-panel"><div class="section-heading"><div><h2>${state.after?'가상 복구 시나리오':'현재 관측 기준 · 개선 전'}</h2><p>${state.after?'선택 설비의 정상 복구를 가정한 결과 · 실제 API 관측값이 아닙니다.':'운영중지 설비를 선택해 복구 결과를 비교하세요. 시설 모집단은 개선 전 선택조건으로 고정합니다.'}</p></div>${exportButton()}</div><div class="simulation-metrics"><div><small>정상 가용 정격출력</small><strong>${show(b.normal_kw)} <em>→</em> ${show(a.normal_kw)} <em>kW</em></strong></div><div><small>회복 정격출력 · 현재 필터</small><strong class="teal-text">${connected?'+':''}${show(m.recovered_kw)} <em>kW</em></strong></div><div><small>회복률 · 기준 운영중지 출력 대비</small><strong>${show(m.recovery_rate*100)} <em>%</em></strong></div><div><small>운영중지 출력 감소량</small><strong>${show(m.stopped_kw_reduction)} <em>kW</em></strong></div><div><small>운영중지 출력</small><strong>${show(b.stopped_kw)} <em>→</em> ${show(a.stopped_kw)} <em>kW</em></strong></div><div><small>정상 설비 수</small><strong>${show(b.normal_count)} <em>→</em> ${show(a.normal_count)} <em>기</em></strong></div><div><small>운영중지 설비 수</small><strong>${show(b.stopped_count)} <em>→</em> ${show(a.stopped_count)} <em>기</em></strong></div><div><small>기준 상위 ${connected?m.baseline_top_count:'—'}기 중 미복구 · 현재 필터</small><strong>${show(m.baseline_top_remaining)} <em>기</em></strong></div></div><div class="selection-chips">${list.length?list.map(r=>`<button data-remove="${esc(r.charger_id)}">${esc(r.name)} · ${fmt(r.power_kw)}kW ${icon('close',13)}</button>`).join(''):'<p>'+ (connected?'아래 목록에서 운영중지 설비를 선택하세요. 빈 선택의 변화량은 0입니다.':'데이터 미수집 · 선택할 설비 데이터 없음')+'</p>'}</div><div class="conservation-note">총 정격출력 ${show(b.total_kw)} → ${show(a.total_kw)} kW · 상태불확실·점검 ${show(b.uncertain_kw)} → ${show(a.uncertain_kw)} kW 유지${state.selected.size>list.length?' · 다른 필터에서 선택한 설비 '+(state.selected.size-list.length)+'기':''}</div></article><article class="panel list-panel"><div class="section-heading"><div><h2>${state.after?'복구 후 잔여 운영중지 설비':'가상 복구 대상 선택'}</h2><p>주변 대체망이 변한 시설의 잔여 점수도 재계산합니다.</p></div></div>${priorityTable(rows)}</article>`;}
 function selectStation(id,charger=null){state.alternatives=[];state.alternativeMessage='';const s=(current()?.map_stations||current()?.stations||[]).find(s=>s.id===id);state.station=id;state.charger=charger;state.maintenance=null;state.searchOpen=false;renderAutocomplete();renderDetail();renderMap(filtered());stationMap?.flyTo(s);$('#detail-title')?.focus();if(charger)root.querySelector(`[data-detail-charger="${CSS.escape(charger)}"]`)?.scrollIntoView({block:'nearest'});if(state.mode==='live'&&state.tab!=='overview'&&s?.statId){const selected=id;fetch('/api/analysis/stations/'+encodeURIComponent(s.statId)+'/alternatives?radius='+state.radius,{cache:'no-store'}).then(async response=>{if(!response.ok)throw new Error();return response.json();}).then(data=>{if(state.station!==selected)return;state.alternativeMessage=data.message||('\uc8fc\ubcc0 \ub300\uccb4\ub9dd '+(data.total??0)+'\uae30');state.alternatives=inventoryDashboard({items:data.items||[],classification_verified:state.classificationVerified}).map_stations.filter(a=>a.id!==id).map(a=>({...a,map_role:'alternative'}));renderMap(filtered());renderDetail();}).catch(()=>{if(state.station===selected){state.alternativeMessage='\uc8fc\ubcc0 \ub300\uccb4\ub9dd \uacb0\uacfc \uc900\ube44 \uc911';renderDetail();}});}}
 function renderDetail(){const host=$('#detail-root'),s=(current()?.map_stations||current()?.stations||[]).find(s=>s.id===state.station);if(!s||['maintenance','quality'].includes(state.tab)){host.innerHTML='';return;}const target=(current()?.stations||[]).some(t=>t.id===s.id),priority=[...(current()?.priorities||[]),...(current()?.held||[])];host.innerHTML=`<div class="drawer-backdrop" data-action="close-detail"></div><aside class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><div class="drawer-heading"><span class="eyebrow">${current()?.operations_dataset?'ME OPERATIONAL OBSERVATION':target?'STATION DETAIL':'주변 대체망 · 실적 집계 제외'}</span><button class="icon-button" data-action="close-detail" aria-label="상세 닫기">${icon('close')}</button></div><h2 id="detail-title" tabindex="-1">${esc(s.name)}</h2>${state.mode==='live'?`<p class="detail-note">statId: ${esc(s.statId||s.id.replace(/^ME:/,''))} \u00b7 \ucda9\uc804\uae30 ${s.chargers.length}\uae30</p>`:''}<p class="detail-address">${icon('pin',15)}${esc(s.address||'주소 데이터 없음')}</p>${state.tab==='simulation'&&state.after?'<p class="scenario-label">가상 복구 시나리오 · 실제 API 관측값 아님</p>':''}<div class="detail-stats"><div><small>${current()?.operations_dataset?'데이터 범위':'2025년 최근 실제 급속 이용실적'}</small><b>${current()?.operations_dataset?'환경공단 서울 원자료':fmt(s.annual_kwh)} <em>${!current()?.operations_dataset&&s.annual_kwh!=null?'kWh':''}</em></b></div><div><small>${current()?.operations_dataset&&!state.classificationVerified?'원자료 출력 / 설비':'정격출력 / 급속 설비'}</small><b>${fmt(s.totals?.total_kw)} <em>kW / ${s.totals?.charger_count??'데이터 없음'}기</em></b></div><div><small>${state.radius}m 외부 정상 대체망</small><b>${fmt(s.alternative_kw)} <em>${s.alternative_kw!=null?'kW':''}</em></b></div></div><h3>충전기 운영상태 · ${time(current()?.observed_at)}</h3><div class="charger-cards">${s.chargers.map(c=>{const r=priority.find(r=>r.charger_id===c.id);return `<div data-detail-charger="${esc(c.id)}" class="charger-card ${state.charger===c.id?'focused-charger':''}"><div><b>${state.mode==='live'?'chgerId: ':''}${esc(c.chgerId||c.id)}</b><span class="badge ${['AVAILABLE','CHARGING','RESTORED'].includes(c.display_status)?'normal':c.display_status==='STOPPED'?'stopped':c.display_status==='MAINTENANCE'?'maintenance':'uncertain'}">${esc(c.status_label||labels[c.display_status]||'상태 확인 필요')}</span></div><p>${fmt(c.power_kw)} ${c.power_kw!=null?'kW':''} · ${c.last_verified_at?'상태 확인 '+time(c.last_verified_at):'상태 확인 필요'}</p>${state.mode==='live'?`<dl class="metadata"><dt>유형 코드 (chgerType)</dt><dd>${esc(c.chgerType??'미제공')} / ${esc(c.type_label||'분류 보류')}</dd><dt>상태 코드 (stat)</dt><dd>${esc(c.stat??'미제공')}</dd><dt>상태 갱신시각 (statUpdDt)</dt><dd>${esc(c.statUpdDt??'미제공')}</dd></dl>`:''}${r&&state.tab==='simulation'?`<label class="check-label"><input data-charger="${esc(c.id)}" type="checkbox" ${state.selected.has(c.id)?'checked':''} ${r.eligible?'':'disabled'}> 가상 복구 대상으로 선택</label>`:''}${r?`<small class="impact-breakdown">${r.eligible?`D = ${fmt(r.demand_factor,3)} · 최근 실제 이용 중요도<br>Q = ${fmt(r.share_factor,3)} · 시설 내 정격출력 비율<br>B = ${fmt(r.shortage_factor,3)} · 주변 대체망 부족도<br>Impact = (D + Q + B) / 3 = ${fmt(r.score,3)}`:esc(r.reasons.join(' · '))}</small>`:''}</div>`;}).join('')}</div><p class="detail-note" id="alternative-status">${esc(state.alternativeMessage)}</p><h3>자료와 분석 근거</h3><p class="detail-note">${esc(s.quality_flags?.length?s.quality_flags.join(' · '):current()?.operations_dataset?'환경공단 등록 시설 · 서울시 소유 및 D1 동일시설 확정 아님':target?'승인된 시설 · 분석 요건 충족':'주변 대체망 시설 · 실적 연결 없음')}${state.mode==='sample'?' · 샘플 데이터':''}</p><dl class="metadata"><dt>관측시각</dt><dd>${time(current()?.observed_at)}</dd><dt>스냅샷</dt><dd>${esc(state.base?.snapshot_id)}</dd><dt>공식 / 반경</dt><dd>impact-mean-v0.2 / ${state.radius}m</dd><dt>산식</dt><dd>(D + Q + B) / 3 · 0~1</dd></dl></aside>`;}

 async function calculate(){if(!state.base)return;const request=++state.scenarioRequest,selected=[...state.selected],baseline=state.base.analysis_run_id;try{const result=await api('simulations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({analysis_run_id:baseline,charger_ids:selected})});if(disposed||request!==state.scenarioRequest||state.base?.analysis_run_id!==baseline)return;state.sim=result;render();}catch(e){if(request!==state.scenarioRequest)return;toast(e.message);state.selected=new Set(state.sim?.charger_ids||[]);render();}}
 async function maintenanceLoad(){if(!state.station||!state.base)return;try{state.maintenance=await api(`stations/${encodeURIComponent(state.station)}/maintenance?`+query({analysis_run_id:state.base.analysis_run_id,weekday:state.weekday,duration_minutes:state.duration,year:2025,allowed_start:state.allowedStart,allowed_end:state.allowedEnd}));render();}catch(e){toast(e.message);}}
 function exportCsv(){const rows=filtered(),t=state.tab==='simulation'?state.sim:null;const lines=[['mode','snapshot_id','analysis_run_id','observed_at','formula','radius_m','view','recovered_kw','before_normal_kw','after_normal_kw','before_stopped_kw','after_stopped_kw','baseline_top_remaining'],[state.mode,state.base?.snapshot_id,state.base?.analysis_run_id,state.base?.observed_at,'impact-mean-v0.2',state.radius,state.tab==='simulation'&&state.after?'after':'before',t?.recovered_kw||0,t?.before?.totals.normal_kw??state.base?.totals.normal_kw,t?.after?.totals.normal_kw??state.base?.totals.normal_kw,t?.before?.totals.stopped_kw??state.base?.totals.stopped_kw,t?.after?.totals.stopped_kw??state.base?.totals.stopped_kw,t?.baseline_top_remaining??Math.min(10,state.base?.priorities?.length||0)],[],['station_id','name','district','normal_kw','stopped_kw','uncertain_kw','total_kw','annual_kwh','quality_flags'],...rows.map(s=>[s.id,s.name,s.district,s.totals.normal_kw,s.totals.stopped_kw,s.totals.uncertain_kw,s.totals.total_kw,s.annual_kwh,s.quality_flags.join(';')]),[],['selected_charger_id'],...[...state.selected].map(id=>[id])];const csv='\ufeff'+lines.map(row=>row.map(v=>{let value=String(v??'');if(/^[=+@\-\t\r]/.test(value))value="'"+value;return '"'+value.replaceAll('"','""')+'"';}).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`seoul-charge-${state.mode}-${state.tab==='simulation'&&state.after?'after':'before'}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 async function onClick(e){
  if(e.target.id==='search'){state.searchOpen=true;state.searchIndex=-1;renderAutocomplete();return;}
  const b=e.target.closest('button,[data-station],[data-action]');if(!b)return;
  if(b.dataset.searchResult){chooseSearch(b.dataset.searchResult);return;}
  if(b.dataset.tab&&state.mode==='live'&&['priorities','maintenance','simulation','quality'].includes(b.dataset.tab)){state.tab=b.dataset.tab;state.station=null;render();return;}if(b.dataset.tab){if(b.dataset.tab==='quality'){try{state.quality=await api('data-quality');}catch{}}if(state.mode==='live'&&state.base?.core_dataset&&!state.base?.analysis_run_id&&state.core?.total>0&&['priorities','simulation','maintenance'].includes(b.dataset.tab)&&state.classificationVerified){try{const analysis=await api('overview?'+query());state.base={...analysis,core_dataset:true,provider_inventory:false};}catch{toast('D1/D2 분석 준비 중 · 실제 데이터 연결은 유지됩니다.');}}state.tab=b.dataset.tab;state.station=null;state.charger=null;state.searchOpen=false;render();return;}
  if(b.dataset.station){selectStation(b.dataset.station,b.dataset.focusCharger||null);return;}
  if(b.dataset.radius){if(Number(b.dataset.radius)===state.radius)return;state.radius=Number(b.dataset.radius);if(state.mode==='live'&&state.tab==='overview'){render();return;}state.base=null;state.sim=null;state.selected.clear();state.after=false;state.station=null;state.scenarioRequest++;await load();return;}
  if(b.dataset.view&&state.tab==='simulation'){state.after=b.dataset.view==='after';render();return;}
  if(b.dataset.remove&&state.tab==='simulation'){state.selected.delete(b.dataset.remove);await calculate();return;}
  const a=b.dataset.action;if(a==='stations-prev'||a==='stations-next'){state.tablePage+=a==='stations-next'?1:-1;renderContent(filtered());return;}
  if(a==='refresh'){await load(true);return;}
  if(a==='reset'){state.scenarioRequest++;state.selected.clear();state.sim=null;state.after=false;render();return;}
  if(a==='rebase'){state.selected.clear();await load();return;}
  if(a==='filters-reset'){for(const k of ['district','search','status','qualityFilter','powerMin','powerMax']){state[k]='';$('#'+k).value='';}state.searchStation=null;state.station=null;state.searchOpen=false;render();stationMap?.reset();return;}
  if(a==='export'){exportCsv();return;}
  if(a==='close-detail'){state.station=null;state.charger=null;renderDetail();renderMap(filtered());return;}
  if(a==='maintenance'){await maintenanceLoad();return;}
  if(a==='admin'){try{if(state.mode==='live'){const response=await fetch('/api/analysis/matches',{cache:'no-store'});if(!response.ok)throw new Error('분석 결과 준비 중');state.coreMatches=await response.json();}else state.admin=await api('admin/matches');render();$('.admin-panel')?.scrollIntoView({behavior:'smooth'});}catch(err){toast(err.message);}return;}
  if(a==='map-reset'){stationMap?.reset();return;}
  if(a==='zoom-in'||a==='zoom-out')stationMap?.zoomBy(a==='zoom-in'?1:-1);
 }
 async function onChange(e){if(e.target.closest('#content')&&state.mode==='live'&&state.tab!=='overview')return;const el=e.target;
  if(el.dataset.charger){if(state.tab!=='simulation')return;if(el.checked)state.selected.add(el.dataset.charger);else state.selected.delete(el.dataset.charger);await calculate();return;}
  if(el.id==='mode'){state.mode=el.value;state.base=null;state.sim=null;state.selected.clear();state.station=null;state.charger=null;state.after=false;state.latestId=null;state.scenarioRequest++;state.searchStation=null;await load();return;}
  if(el.id==='district'){state.district=el.value;state.station=null;state.charger=null;state.searchStation=null;state.search='';state.searchOpen=false;$('#search').value='';state.maintenance=null;render();stationMap?.district(state.district);return;}
  if(['status','qualityFilter','powerMin','powerMax'].includes(el.id)){state[el.id]=el.value;state.station=null;state.maintenance=null;render();return;}
  if(['weekday','duration','allowedStart','allowedEnd'].includes(el.id)){state[el.id]=Number(el.value);state.maintenance=null;return;}
  if(el.id==='maintenanceStation'){state.station=el.value;state.maintenance=null;render();return;}
  if(el.id==='matchSource'){const cs=state.admin.candidates.find(c=>c.source_name===el.value)?.candidates||[];$('#match-candidates').innerHTML=cs.map(c=>`<p><b>${esc(c.name)}</b> · 유사도 ${fmt(c.similarity*100)}%<br>${esc(c.address)} · 좌표 ${fmt(c.lat,6)}, ${fmt(c.lon,6)}</p>`).join('')||'후보 없음';}
 }
 async function onSubmit(e){if(e.target.id!=='match-form')return;e.preventDefault();const f=e.target,fd=new FormData(f),body=Object.fromEntries(fd),token=body.token;delete body.token;for(const n of ['physical_verified','sharing_verified','access_verified','compatible_verified','fast_only_history_verified'])body[n]=fd.has(n);try{await api('admin/matches/'+encodeURIComponent(body.station_id),{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify(body)});f.querySelector('[name="token"]').value='';state.admin=await api('admin/matches');toast('검토 근거를 저장했습니다. 새 분석에 적용됩니다.');await load(true);}catch(err){toast(err.message);}}
 function onInput(e){if(e.target.closest('#content')&&state.mode==='live'&&state.tab!=='overview')return;if(e.target.id==='search'){state.search=e.target.value;state.searchStation=null;state.searchOpen=true;state.searchIndex=-1;state.station=null;state.maintenance=null;render();}}
 function onFocus(e){if(e.target.id==='search'){state.searchOpen=true;renderAutocomplete();}}
 function onOutside(e){if(!e.target.closest('.search-label')){state.searchOpen=false;renderAutocomplete();}}
 function onKey(e){
  if(e.target.id==='search'){
   if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();state.searchOpen=true;const n=state.searchCandidates.length;state.searchIndex=n?(state.searchIndex+(e.key==='ArrowDown'?1:-1)+n)%n:-1;renderAutocomplete();return;}
   if(e.key==='Enter'&&state.searchOpen){e.preventDefault();const s=state.searchCandidates[Math.max(0,state.searchIndex)];if(s)chooseSearch(s.id);return;}
   if(e.key==='Escape'){state.searchOpen=false;renderAutocomplete();return;}
   if(e.key==='Tab'){state.searchOpen=false;renderAutocomplete();}
  }
  if(e.key==='Escape'){state.station=null;state.charger=null;renderDetail();renderMap(filtered());}
  if(e.key==='Tab'){const d=$('.detail-drawer');if(d){const fs=[...d.querySelectorAll('button,input:not(:disabled),a,[tabindex="0"]')];if(e.shiftKey&&document.activeElement===fs[0]){e.preventDefault();fs.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===fs.at(-1)){e.preventDefault();fs[0]?.focus();}}}
 }
 root.addEventListener('click',onClick);root.addEventListener('change',onChange);root.addEventListener('input',onInput);root.addEventListener('submit',onSubmit);root.addEventListener('keydown',onKey);root.addEventListener('focusin',onFocus);document.addEventListener('pointerdown',onOutside);
 let lastLiveRefresh=0;const poll=setInterval(()=>{if(disposed||state.mode!=='live'||state.loading||state.tab!=='overview')return;if(state.base&&Date.now()-lastLiveRefresh<60000)return;lastLiveRefresh=Date.now();load(true);},5000);
 if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(()=>{charts.forEach(c=>c.resize());});observer.observe(root);}render();load();
 return ()=>{disposed=true;clearInterval(poll);clearTimeout(toastTimer);charts.forEach(c=>c.dispose());stationMap?.destroy();observer?.disconnect();root.removeEventListener('click',onClick);root.removeEventListener('change',onChange);root.removeEventListener('input',onInput);root.removeEventListener('submit',onSubmit);root.removeEventListener('keydown',onKey);root.removeEventListener('focusin',onFocus);document.removeEventListener('pointerdown',onOutside);};
}
